/**
 * Demo-mode Shadow AI adapter. Same interface as connected mode
 * (list / detail / importCsv / decide / portfolio), backed by aiDemo.json —
 * real engine output for a sample clinic, generated by
 * backend/scripts/build_ai_demo.py. Decisions are kept in this browser only.
 */
// Loaded on first use so the sample data stays out of the main bundle.
let demoPromise = null;
const getDemo = () => (demoPromise ??= import('./aiDemo.json').then(m => m.default));

const STORE_KEY = 'securityos_ai_demo_v1';
const LEVEL_ORDER = { critical: 0, high: 1, medium: 2, low: 3 };
const OPEN = new Set(['unreviewed', 'under_review']);
const LABELS = {
  approved: 'Approved', approved_business: 'Approved on business plan', under_review: 'Under review',
  blocked: 'Blocked', risk_accepted: 'Risk accepted', unreviewed: 'Not reviewed',
};

function loadDecisions() {
  try { return JSON.parse(localStorage.getItem(STORE_KEY)) ?? {}; } catch { return {}; }
}
function saveDecisions(d) {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(d)); } catch { /* storage unavailable */ }
}

const STATIC_ACTIONS = {
  blocked: { action: 'confirm_removed', label: "Confirm it's removed",
    detail: "Revoke the app's Microsoft 365 / Google consent and check it doesn't show up in the next scan." },
  approved: { action: 'none', label: 'Approved',
    detail: 'Keep it on the approved-tools list and review it at the next policy review.' },
};
STATIC_ACTIONS.approved_business = STATIC_ACTIONS.approved;

function applyDecision(demo, base, record) {
  if (!record) return base;
  const status = record.decision;
  let risk = base.risk;
  if (status === 'approved_business' && demo.business_risk[base.app_key]) {
    const b = demo.business_risk[base.app_key];
    risk = { score: b.score, level: b.level, plan_assumed: 'business', plan_label: b.plan_label, top_factors: b.top_factors };
  }
  return {
    ...base,
    status,
    status_label: LABELS[status],
    decision: { ...record, label: LABELS[status] },
    risk,
    recommended_action: STATIC_ACTIONS[status] ?? base.recommended_action,
  };
}

function inventory(demo) {
  const decisions = loadDecisions();
  const apps = demo.inventory.apps.map(a => applyDecision(demo, a, decisions[a.app_key]?.at(-1)));
  apps.sort((a, b) =>
    (OPEN.has(a.status) ? 0 : 1) - (OPEN.has(b.status) ? 0 : 1)
    || LEVEL_ORDER[a.risk.level] - LEVEL_ORDER[b.risk.level]
    || b.risk.score - a.risk.score || b.user_count - a.user_count);
  const byLevel = { critical: 0, high: 0, medium: 0, low: 0 };
  apps.forEach(a => { byLevel[a.risk.level] += 1; });
  const needs = apps.filter(a => OPEN.has(a.status) && ['critical', 'high'].includes(a.risk.level));
  return {
    ...demo.inventory,
    apps,
    summary: {
      ...demo.inventory.summary,
      by_level: byLevel,
      needs_attention: needs.length,
      unreviewed: apps.filter(a => OPEN.has(a.status)).length,
      approved: apps.filter(a => a.status.startsWith('approved')).length,
      blocked: apps.filter(a => a.status === 'blocked').length,
      top_risk: needs[0]?.name ?? null,
    },
    can_import: false,
    can_decide: true,
  };
}

function detail(demo, appKey) {
  const base = demo.details[appKey];
  if (!base) throw new Error("That app hasn't been seen in this organization.");
  const history = loadDecisions()[appKey] ?? [];
  const item = applyDecision(demo, base, history.at(-1));
  const business = item.status === 'approved_business' ? demo.business_risk[appKey] : null;
  return {
    ...item,
    risk_factors: business ? business.factors : base.risk_factors,
    risk_if_business: business ? null : base.risk_if_business,
    decision_history: [...history].reverse().map(d => ({ ...d, label: LABELS[d.decision] })),
    can_decide: true,
  };
}

function decide(demo, appKey, body) {
  const all = loadDecisions();
  const record = {
    decision: body.decision,
    note: body.note || null,
    expires_at: body.expires_at || null,
    decided_by_name: 'You (demo)',
    decided_at: new Date().toISOString(),
  };
  all[appKey] = [...(all[appKey] ?? []), record];
  saveDecisions(all);
  return detail(demo, appKey);
}

export function createDemoAi() {
  return {
    key: 'demo',
    list: async () => inventory(await getDemo()),
    detail: async appKey => detail(await getDemo(), appKey),
    importCsv: async () => { throw new Error('Demo mode shows a sample clinic. Sign in to import your own export.'); },
    decide: async (appKey, body) => decide(await getDemo(), appKey, body),
    portfolio: async () => (await getDemo()).msp_rollup,
    sample: { orgName: 'Riverside Health' },
    reset: () => saveDecisions({}),
  };
}
